INSERT IGNORE INTO LIVROS_NOMES (NOME, ESTADO, SUGESTAO_TITULO, SUGESTAO_AUTOR, MOTIVO, CRIADO_EM) SELECT J.NOME, 'PENDENTE', NULLIF(LEFT(J.TITULO, 300), ''), NULLIF(LEFT(J.AUTOR, 200), ''), LEFT(J.MOTIVO, 300), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM VW_LOTE_NOMES J WHERE J.CHAVE = '{{chave}}' AND J.NOME <> ''